from pysat.solvers import Glucose4
from itertools import combinations

V = 27
E = 51

edges = []
for g in range(9):
    for i in range(3):
        for j in range(i+1, 3):
            edges.append((g*3 + i, g*3 + j))

for g in range(8):
    for i in range(3):
        edges.append((g*3 + i, (g+1)*3 + i))

def var_x(v, l):
    return v * 52 + l + 1

def var_y(e, d):
    return 27 * 52 + e * 51 + d

solver = Glucose4()

# Each vertex has exactly one label
for v in range(V):
    solver.add_clause([var_x(v, l) for l in range(52)])
    for l1, l2 in combinations(range(52), 2):
        solver.add_clause([-var_x(v, l1), -var_x(v, l2)])

# Each label is used by at most one vertex
for l in range(52):
    for v1, v2 in combinations(range(V), 2):
        solver.add_clause([-var_x(v1, l), -var_x(v2, l)])

# Each edge has exactly one difference
for e in range(E):
    solver.add_clause([var_y(e, d) for d in range(1, 52)])
    for d1, d2 in combinations(range(1, 52), 2):
        solver.add_clause([-var_y(e, d1), -var_y(e, d2)])

# Each difference is used by exactly one edge
for d in range(1, 52):
    solver.add_clause([var_y(e, d) for e in range(E)])
    for e1, e2 in combinations(range(E), 2):
        solver.add_clause([-var_y(e1, d), -var_y(e2, d)])

# Link x and y
for e_idx, (u, v) in enumerate(edges):
    for l1 in range(52):
        for l2 in range(52):
            if l1 != l2:
                d = abs(l1 - l2)
                # If x(u, l1) and x(v, l2) then y(e, d)
                solver.add_clause([-var_x(u, l1), -var_x(v, l2), var_y(e_idx, d)])

# Symmetry breaking
# 1. Path reversal
for l1 in range(52):
    for l2 in range(l1 + 1):
        solver.add_clause([-var_x(0, l1), -var_x(24, l2)])

# 2. K3 permutation
for l1 in range(52):
    for l2 in range(l1 + 1):
        solver.add_clause([-var_x(0, l1), -var_x(1, l2)])
        solver.add_clause([-var_x(1, l1), -var_x(2, l2)])

print("Solving...")
if solver.solve():
    print("SAT")
    model = solver.get_model()
    labels = [-1] * V
    for v in range(V):
        for l in range(52):
            if model[var_x(v, l) - 1] > 0:
                labels[v] = l
    print(labels)
else:
    print("UNSAT")

