# Let's try a smaller graph first to see if there's a pattern.
# G_{k, n}: n disjoint K_k cliques, connected by k edges.
# Here k=3, n=9.
# Let's try k=3, n=2, 3, 4.

def solve_small(n):
    from pysat.solvers import Cadical153
    from itertools import combinations

    V = 3 * n
    E = 3 * n + 3 * (n - 1)

    edges = []
    for g in range(n):
        for i in range(3):
            for j in range(i+1, 3):
                edges.append((g*3 + i, g*3 + j))

    for g in range(n-1):
        for i in range(3):
            edges.append((g*3 + i, (g+1)*3 + i))

    def var_x(v, l):
        return v * (E + 1) + l + 1

    def var_y(e, d):
        return V * (E + 1) + e * E + d

    solver = Cadical153()

    for v in range(V):
        solver.add_clause([var_x(v, l) for l in range(E + 1)])
        for l1, l2 in combinations(range(E + 1), 2):
            solver.add_clause([-var_x(v, l1), -var_x(v, l2)])

    for l in range(E + 1):
        for v1, v2 in combinations(range(V), 2):
            solver.add_clause([-var_x(v1, l), -var_x(v2, l)])

    for e in range(E):
        solver.add_clause([var_y(e, d) for d in range(1, E + 1)])
        for d1, d2 in combinations(range(1, E + 1), 2):
            solver.add_clause([-var_y(e, d1), -var_y(e, d2)])

    for d in range(1, E + 1):
        solver.add_clause([var_y(e, d) for e in range(E)])
        for e1, e2 in combinations(range(E), 2):
            solver.add_clause([-var_y(e1, d), -var_y(e2, d)])

    for e_idx, (u, v) in enumerate(edges):
        for l1 in range(E + 1):
            for l2 in range(E + 1):
                if l1 != l2:
                    d = abs(l1 - l2)
                    solver.add_clause([-var_x(u, l1), -var_x(v, l2), var_y(e_idx, d)])

    for l1 in range(E + 1):
        for l2 in range(l1 + 1):
            solver.add_clause([-var_x(0, l1), -var_x(V - 3, l2)])

    for l1 in range(E + 1):
        for l2 in range(l1 + 1):
            solver.add_clause([-var_x(0, l1), -var_x(1, l2)])
            solver.add_clause([-var_x(1, l1), -var_x(2, l2)])

    if solver.solve():
        model = solver.get_model()
        labels = [-1] * V
        for v in range(V):
            for l in range(E + 1):
                if model[var_x(v, l) - 1] > 0:
                    labels[v] = l
        print(f"n={n} SAT: {labels}")
    else:
        print(f"n={n} UNSAT")

for n in range(2, 5):
    solve_small(n)
